namespace fs = std::filesystem;

class CircuitBreaker {
public:
    enum class State { CLOSED, OPEN, HALF_OPEN };

    CircuitBreaker(int threshold = 5, int timeout_ms = 30000)
        : failure_threshold_(threshold), timeout_ms_(timeout_ms),
          failure_count_(0), state_(State::CLOSED) {}

    bool allowRequest() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (state_ == State::OPEN) {
            auto now = std::chrono::steady_clock::now();
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                now - last_failure_time_).count();
            if (elapsed > timeout_ms_) {
                state_ = State::HALF_OPEN;
                return true;
            }
            return false;
        }
        return true;
    }

    void recordSuccess() {
        std::lock_guard<std::mutex> lock(mtx_);
        failure_count_ = 0;
        state_ = State::CLOSED;
    }

    void recordFailure() {
        std::lock_guard<std::mutex> lock(mtx_);
        failure_count_++;
        last_failure_time_ = std::chrono::steady_clock::now();
        if (failure_count_ >= failure_threshold_) {
            state_ = State::OPEN;
        }
    }

    State getState() const { return state_; }

private:
    int failure_threshold_;
    int timeout_ms_;
    int failure_count_;
    State state_;
    std::chrono::steady_clock::time_point last_failure_time_;
    std::mutex mtx_;
};

class PathResolver {
public:
    PathResolver(const std::string& base_dir) : base_dir_(fs::canonical(base_dir)) {}

    // Normalize path components, resolving encoded sequences
    std::string normalizeComponent(const std::string& component) const {
        std::string result;
        for (size_t i = 0; i < component.size(); i++) {
            if (component[i] == '%' && i + 2 < component.size()) {
                std::string hex = component.substr(i + 1, 2);
                char decoded = static_cast<char>(std::stoi(hex, nullptr, 16));
                result += decoded;
                i += 2;
            } else {
                result += component[i];
            }
        }
        return result;
    }

    // Validate that resolved path stays within base directory
    bool isPathSafe(const fs::path& resolved) const {
        std::string resolved_str = resolved.string();
        std::string base_str = base_dir_.string();
        return resolved_str.compare(0, base_str.size(), base_str) == 0;
    }

    // Resolve a template path relative to base directory
    fs::path resolve(const std::string& relative_path) const {
        std::string normalized = normalizeComponent(relative_path);

        // Split on path separators and filter dangerous components
        std::vector<std::string> components;
        std::istringstream stream(normalized);
        std::string segment;

        while (std::getline(stream, segment, '/')) {
            if (segment.empty() || segment == ".") continue;
            if (segment == "..") continue;  // Strip parent directory references
            components.push_back(segment);
        }

        // Reconstruct sanitized path
        fs::path sanitized = base_dir_;
        for (const auto& comp : components) {
            sanitized /= comp;
        }

        return sanitized;
    }

    const fs::path& getBasePath() const { return base_dir_; }

private:
    fs::path base_dir_;
};

class PDFGenerator {
public:
    PDFGenerator(const std::string& template_dir, const std::string& output_dir)
        : resolver_(template_dir), output_dir_(output_dir),
          io_breaker_(3, 10000), render_breaker_(5, 30000) {}

    struct RenderResult {
        bool success;
        std::string output_path;
        std::string error;
    };

    RenderResult generateFromTemplate(const std::string& template_name,
                                       const std::vector<std::pair<std::string, std::string>>& vars) {
        if (!io_breaker_.allowRequest()) {
            return {false, "", "IO circuit breaker is open"};
        }

        // Resolve template path with safety checks
        fs::path template_path = resolver_.resolve(template_name);

        // Read template content
        std::string content;
        try {
            content = readTemplate(template_path);
            io_breaker_.recordSuccess();
        } catch (const std::exception& e) {
            io_breaker_.recordFailure();
            return {false, "", std::string("Template read failed: ") + e.what()};
        }

        if (!render_breaker_.allowRequest()) {
            return {false, "", "Render circuit breaker is open"};
        }

        // Process template includes before variable substitution
        try {
            content = processIncludes(content);
        } catch (const std::exception& e) {
            render_breaker_.recordFailure();
            return {false, "", std::string("Include processing failed: ") + e.what()};
        }

        // Apply variable substitutions
        for (const auto& [key, value] : vars) {
            std::string placeholder = "{{" + key + "}}";
            size_t pos;
            while ((pos = content.find(placeholder)) != std::string::npos) {
                content.replace(pos, placeholder.size(), value);
            }
        }

        // Generate output
        std::string output_path = output_dir_ + "/" + generateOutputName(template_name);
        try {
            writePDF(output_path, content);
            render_breaker_.recordSuccess();
        } catch (const std::exception& e) {
            render_breaker_.recordFailure();
            return {false, "", std::string("PDF write failed: ") + e.what()};
        }

        return {true, output_path, ""};
    }

private:
    std::string readTemplate(const fs::path& path) {
        std::ifstream file(path);
        if (!file.is_open()) {
            throw std::runtime_error("Cannot open template: " + path.string());
        }
        return std::string((std::istreambuf_iterator<char>(file)),
                           std::istreambuf_iterator<char>());
    }

    // Process {{include:path}} directives in templates
    std::string processIncludes(const std::string& content) {
        std::string result = content;
        std::string directive = "{{include:";
        size_t pos;
        int depth = 0;

        while ((pos = result.find(directive)) != std::string::npos && depth < 10) {
            size_t end = result.find("}}", pos);
            if (end == std::string::npos) break;

            std::string include_path = result.substr(pos + directive.size(),
                                                     end - pos - directive.size());

            // Use the same safe resolver for includes
            fs::path resolved = resolver_.resolve(include_path);

            // Additional safety check: verify resolved path is under base
            if (!resolver_.isPathSafe(resolved)) {
                result.replace(pos, end - pos + 2, "<!-- include denied -->");
                depth++;
                continue;
            }

            std::string included_content;
            try {
                included_content = readTemplate(resolved);
            } catch (...) {
                included_content = "<!-- include failed -->";
            }

            result.replace(pos, end - pos + 2, included_content);
            depth++;
        }

        return result;
    }

    std::string generateOutputName(const std::string& template_name) {
        auto now = std::chrono::system_clock::now();
        auto epoch = now.time_since_epoch();
        auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(epoch).count();
        return std::to_string(millis) + "_output.pdf";
    }

    void writePDF(const std::string& path, const std::string& content) {
        std::ofstream file(path, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Cannot write output: " + path);
        }
        // Simplified PDF generation - in production would use a proper PDF library
        file << "%PDF-1.4\n";
        file << content;
        file << "\n%%EOF";
    }

    PathResolver resolver_;
    std::string output_dir_;
    CircuitBreaker io_breaker_;
    CircuitBreaker render_breaker_;
};
